select * from chat_messages
where conversation_id = #{conversationId}
order by created_at asc

SELECT * FROM chat_messages
WHERE
    (
        -- 用户发给客服
        sender_type = 'user' AND sender_id = #{userId}
        )
   OR
    (
        -- 客服发给用户（关键：查 receive_user_id）
        sender_type = 'admin' AND sender_id = #{adminId} AND receive_user_id = #{userId}
        )
ORDER BY created_at ASC
